new=old+'''# ---------- one drop per add ----------
# The board's adds are matched, in order, to the weakest flex-eligible bench players still standing, so the
# second add is priced against the second drop instead of reusing the first one. A position is never cut
# below its floor. The bench verdicts follow the same pairing, so a card and the board never disagree.
$DROPFOR = @{}
try {
  $cnt = @{}; foreach ($k0 in $posCount.Keys) { $cnt[$k0] = $posCount[$k0] }
  $pool = @(); foreach ($b in $benchList) { $bp = PX $b.player; if ($bp -and $bp.pos -in "RB","WR","TE") { $vv = $bp.value; if ($bp.inj -in "IR","Out","PUP") { $vv = $vv * 0.5 }; $pool += @{ key = $b.player; name = $bp.name; pos = $bp.pos; v = $vv; value = $bp.value } } }
  $pool = @($pool | Sort-Object { $_.v })
  $used = @{}; $move = 0
  foreach ($w in $waivers) {
    if ($w.pos -notin "RB","WR","TE") { continue }
    $pick = $null
    foreach ($c in $pool) { if ($used.ContainsKey($c.key)) { continue }; $fl = $(if ($posFloor.ContainsKey($c.pos)) { $posFloor[$c.pos] } else { 0 }); if ($cnt[$c.pos] -le $fl) { continue }; $pick = $c; break }
    if (-not $pick) { $w.dropFor = ""; $w.chainGain = $null; $w.chainN = 0; $w.why = $w.why + "; no bench spot left to give up without cutting a position below its floor"; continue }
    $move++; $used[$pick.key] = $true; $cnt[$pick.pos]--
    $g = Rnd ($w.value - $pick.value) 1
    $w.dropFor = $pick.name; $w.chainGain = $g; $w.chainN = $move
    if ($g -ge 1.5) { $w.why = $w.why + "; drop " + $pick.name + " (+" + ("{0:0.0}" -f $g) + "/wk" + $(if ($move -gt 1) { ", move " + $move } else { "" }) + ")"; $DROPFOR[$pick.key] = @{ add = $w.player; gain = $g; n = $move } }
    else { $w.why = $w.why + "; would cost " + $pick.name + " for +" + ("{0:0.0}" -f $g) + "/wk - not worth the spot" }
  }
  foreach ($r in $roster) {
    if ($r.slot -notlike "BN*" -or -not $r.key) { continue }
    if ($DROPFOR.ContainsKey($r.key)) { $d0 = $DROPFOR[$r.key]; $pre = "Upgrade" + $(if ($d0.n -gt 1) { " (move " + $d0.n + ")" } else { "" }) + ": drop for "; if ((N $r.weekVsValue) -ge 1.25 -and $r.status -eq "Upcoming") { $pre = "Upgrade after this week (his best week is now): drop for " }; $r.verdict = $pre + $d0.add + " (+" + ("{0:0.0}" -f $d0.gain) + "/wk)" }
    elseif ([string]$r.verdict -like "Upgrade*") { $r.verdict = "Hold - no free agent worth his spot right now" }
  }
} catch { Log ("  add/drop pairing failed: " + $_.Exception.Message) }
'''
